// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, address potentialTo, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(potentialTo != address(0));

        CalleeChecker callee = new CalleeChecker(from);

        address[] memory tos = new address[](1);
        tos[0] = potentialTo;

        bool ok;
        try c.transfer(from, address(callee), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract CalleeChecker {
    address public expectedFirst;
    constructor(address _expectedFirst) { expectedFirst = _expectedFirst; }

    function transferFrom(address a, address b, uint256) external {
        require(a == expectedFirst, "first address mismatch");
    }

    fallback() external payable {
        if (msg.data.length >= 4 + 32) {
            bytes memory data = msg.data[4:];
            address a;
            assembly { a := mload(add(data, 32)) }
            if (a != expectedFirst) revert("first address mismatch");
        }
    }
}
